/* Seeded search for error sets of the list of X^l (PlaneCount review of bp1_c1562504, draft).
 *
 * Field F = F_p[i]/(i^2+1), p = 2^31-1; grid D = mu_n generated by z = w^(2^31/n),
 * w = (1+2i)^(p-1) (the generator fixed in sr_planecount_ref.py).
 * A polynomial P (deg P < k) with exact agreement a and error set B (b = n-a) exists iff
 * the locator L_B has zero coefficients at X^(b-j), j in [d+1, l-k], d = l-a
 * (checked against brute force in sr_planecount_ref.py).  So L_B = X^b + sum_{e in E} c_e X^e
 * with E = {0..b-l+k-1} u {b-d..b-1}, u = |E| = 2b+k-n unknowns, and L_B(x) = 0 is linear in c.
 * A seed S of u points of B determines c when its u x u system is nonsingular; otherwise the
 * program extends S by every further point in increasing order (depth-first) until the system has
 * a unique solution, so every B containing S is found either way.  A candidate is reported when its
 * L has exactly b roots on D.  Candidates are then checked exactly by sr_planecount_check.py.
 *
 * Usage: sr_planecount n k l b all            (every u-subset as a seed; small n only)
 *        sr_planecount n k l b rand N seed     (N seeds {1} u random (u-1)-subset of D\{1})
 *        sr_planecount n k l b line N seed     (N seeds {1} u random (u-2)-subset; one-parameter family)
 * Output: one line per distinct candidate (hex mask of B, bit j = z^j), then a summary line.
 * Build: gcc -O2 -Wall -o sr_planecount sr_planecount.c
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef uint64_t u64;
typedef struct { u64 a, b; } fe; /* a + b i, each in [0, p) */
static const u64 P = 2147483647ULL;

static inline u64 red(u64 x) { x = (x & P) + (x >> 31); x = (x & P) + (x >> 31); return x >= P ? x - P : x; }
static inline u64 mmul(u64 x, u64 y) { return red(x * y); }
static inline fe fadd(fe x, fe y) { fe r = { red(x.a + y.a), red(x.b + y.b) }; return r; }
static inline fe fsub(fe x, fe y) { fe r = { red(x.a + P - y.a), red(x.b + P - y.b) }; return r; }
static inline fe fmul(fe x, fe y) {
    fe r = { red(mmul(x.a, y.a) + P - mmul(x.b, y.b)), red(mmul(x.a, y.b) + mmul(x.b, y.a)) };
    return r;
}
static inline int fzero(fe x) { return x.a == 0 && x.b == 0; }
static u64 mpow(u64 x, u64 e) { u64 r = 1; while (e) { if (e & 1) r = mmul(r, x); x = mmul(x, x); e >>= 1; } return r; }
static fe fpow(fe x, u64 e) { fe r = { 1, 0 }; while (e) { if (e & 1) r = fmul(r, x); x = fmul(x, x); e >>= 1; } return r; }
static fe finv(fe x) {
    u64 nrm = red(mmul(x.a, x.a) + mmul(x.b, x.b)), ni = mpow(nrm, P - 2);
    fe r = { mmul(x.a, ni), mmul(red(P - x.b), ni) };
    return r;
}

static int n, k, l, b, d, u, E[64];
static fe zp[64];               /* zp[j] = z^j */
static u64 found_masks[1 << 16];
static int nfound;
static u64 n_seeds, n_singular, n_nodes, n_unique;

/* row for point index j: coefficients z^(j e) for e in E, rhs -z^(j b) */
static void row(int j, fe *r) {
    for (int t = 0; t < u; t++) r[t] = zp[(j * E[t]) % n];
    fe one = { 0, 0 }; r[u] = fsub(one, zp[(j * b) % n]);
}

/* Solve the system of the given points. Returns -1 inconsistent, 0 underdetermined, 1 unique (c filled). */
static int solve(const int *pts, int m, fe *c) {
    static fe M[80][65];
    for (int i = 0; i < m; i++) row(pts[i], M[i]);
    int r = 0, piv[64];
    for (int col = 0; col < u && r < m; col++) {
        int s = -1;
        for (int i = r; i < m; i++) if (!fzero(M[i][col])) { s = i; break; }
        if (s < 0) continue;
        if (s != r) for (int t = 0; t <= u; t++) { fe tmp = M[s][t]; M[s][t] = M[r][t]; M[r][t] = tmp; }
        fe iv = finv(M[r][col]);
        for (int t = col; t <= u; t++) M[r][t] = fmul(M[r][t], iv);
        for (int i = 0; i < m; i++) if (i != r && !fzero(M[i][col])) {
            fe f = M[i][col];
            for (int t = col; t <= u; t++) M[i][t] = fsub(M[i][t], fmul(f, M[r][t]));
        }
        piv[r++] = col;
    }
    for (int i = r; i < m; i++) if (!fzero(M[i][u])) return -1;
    if (r < u) return 0;
    for (int i = 0; i < u; i++) c[piv[i]] = M[i][u];
    return 1;
}

static void record(u64 mask) {
    for (int i = 0; i < nfound; i++) if (found_masks[i] == mask) return;
    if (nfound < (1 << 16)) found_masks[nfound++] = mask;
    printf("candidate %016llx\n", (unsigned long long)mask);
}

/* L = X^b + sum c_t X^E[t]; report if it has exactly b roots on D */
static void check(const fe *c) {
    n_unique++;
    int roots = 0, miss = 0; u64 mask = 0;
    for (int j = 0; j < n; j++) {
        fe v = zp[(j * b) % n];
        for (int t = 0; t < u; t++) v = fadd(v, fmul(c[t], zp[(j * E[t]) % n]));
        if (fzero(v)) { roots++; mask |= 1ULL << j; }
        else if (++miss > n - b) return;
    }
    if (roots == b) record(mask);
}

/* every B containing pts[0..m) : extend by points in increasing order beyond 'last' */
static void extend(int *pts, int m, int last) {
    fe c[64];
    n_nodes++;
    int s = solve(pts, m, c);
    if (s < 0) return;
    if (s == 1) { check(c); return; }
    if (m >= b) return;
    for (int j = last + 1; j < n; j++) {
        int in = 0;
        for (int i = 0; i < m; i++) if (pts[i] == j) { in = 1; break; }
        if (in) continue;
        pts[m] = j;
        extend(pts, m + 1, j);
    }
}

static void seed(int *pts) {
    fe c[64];
    n_seeds++;
    int s = solve(pts, u, c);
    if (s == 1) { check(c); return; }
    if (s < 0) return;
    n_singular++;
    int q[64]; memcpy(q, pts, sizeof(int) * u);
    extend(q, u, -1);
}

/* Line mode: m = u-1 seed points.  If their system has rank u-1, the solutions are c0 + t v.
 * L_t(y) = L0(y) + t V(y); a point y with V(y) != 0 is a root for exactly one t = -L0(y)/V(y),
 * a point with V(y) = 0 is a root for every t (if L0(y) = 0) or for none.  Every value of t with
 * exactly b roots gives a candidate, so every B containing the seed is found.  Rank < u-1 falls
 * back to extend(). */
static int fe_less(fe x, fe y) { return x.a != y.a ? x.a < y.a : x.b < y.b; }
static void line_seed(int *pts) {
    static fe M[80][65];
    int m = u - 1;
    n_seeds++;
    for (int i = 0; i < m; i++) row(pts[i], M[i]);
    int r = 0, piv[64], ispiv[64] = { 0 };
    for (int col = 0; col < u && r < m; col++) {
        int s = -1;
        for (int i = r; i < m; i++) if (!fzero(M[i][col])) { s = i; break; }
        if (s < 0) continue;
        if (s != r) for (int t = 0; t <= u; t++) { fe tmp = M[s][t]; M[s][t] = M[r][t]; M[r][t] = tmp; }
        fe iv = finv(M[r][col]);
        for (int t = col; t <= u; t++) M[r][t] = fmul(M[r][t], iv);
        for (int i = 0; i < m; i++) if (i != r && !fzero(M[i][col])) {
            fe f = M[i][col];
            for (int t = col; t <= u; t++) M[i][t] = fsub(M[i][t], fmul(f, M[r][t]));
        }
        piv[r] = col; ispiv[col] = 1; r++;
    }
    for (int i = r; i < m; i++) if (!fzero(M[i][u])) return;          /* inconsistent: no B contains the seed */
    if (r < m) { n_singular++; int q[64]; memcpy(q, pts, sizeof(int) * m); extend(q, m, -1); return; }
    int fc = -1;
    for (int col = 0; col < u; col++) if (!ispiv[col]) { fc = col; break; }
    fe c0[64], v[64], zero = { 0, 0 }, mone = { P - 1, 0 };
    for (int t = 0; t < u; t++) { c0[t] = zero; v[t] = zero; }
    v[fc].a = 1;
    for (int i = 0; i < r; i++) { c0[piv[i]] = M[i][u]; v[piv[i]] = fmul(mone, M[i][fc]); }
    fe tv[64]; int nt = 0, always = 0;
    for (int j = 0; j < n; j++) {
        fe L0 = zp[(j * b) % n], V = zero;
        for (int t = 0; t < u; t++) {
            fe zz = zp[(j * E[t]) % n];
            L0 = fadd(L0, fmul(c0[t], zz)); V = fadd(V, fmul(v[t], zz));
        }
        if (fzero(V)) { if (fzero(L0)) always++; continue; }
        tv[nt++] = fmul(fsub(zero, L0), finv(V));
    }
    for (int i = 1; i < nt; i++) { fe x = tv[i]; int j = i - 1; while (j >= 0 && fe_less(x, tv[j])) { tv[j + 1] = tv[j]; j--; } tv[j + 1] = x; }
    for (int i = 0; i < nt;) {
        int j = i;
        while (j < nt && tv[j].a == tv[i].a && tv[j].b == tv[i].b) j++;
        if (j - i + always >= b) {                     /* recompute exactly at this t */
            fe c[64];
            for (int t = 0; t < u; t++) c[t] = fadd(c0[t], fmul(tv[i], v[t]));
            check(c);
        }
        i = j;
    }
}

static u64 rs[4];
static inline u64 rotl(u64 x, int s) { return (x << s) | (x >> (64 - s)); }
static u64 rnd(void) { /* xoshiro256** */
    u64 r = rotl(rs[1] * 5, 7) * 9, t = rs[1] << 17;
    rs[2] ^= rs[0]; rs[3] ^= rs[1]; rs[1] ^= rs[2]; rs[0] ^= rs[3]; rs[2] ^= t; rs[3] = rotl(rs[3], 45);
    return r;
}
static u64 below(u64 m) { u64 lim = UINT64_MAX - UINT64_MAX % m, x; do x = rnd(); while (x >= lim); return x % m; }

int main(int argc, char **argv) {
    if (argc < 6) { fprintf(stderr, "usage\n"); return 2; }
    n = atoi(argv[1]); k = atoi(argv[2]); l = atoi(argv[3]); b = atoi(argv[4]);
    d = l - (n - b); u = 2 * b + k - n;
    if (n > 64 || d < 0 || u < 1 || u > b || l - k < d + 1) { fprintf(stderr, "bad parameters\n"); return 2; }
    int ne = 0;
    for (int e = 0; e <= b - l + k - 1; e++) E[ne++] = e;
    for (int e = b - d; e <= b - 1; e++) E[ne++] = e;
    if (ne != u) { fprintf(stderr, "exponent count\n"); return 2; }
    fe one = { 1, 2 }, w = fpow(one, P - 1), z = fpow(w, (1ULL << 31) / (u64)n);
    { fe t = fpow(w, 1ULL << 30); if (t.a == 1 && t.b == 0) { fprintf(stderr, "generator\n"); return 2; } }
    zp[0].a = 1; zp[0].b = 0;
    for (int j = 1; j < n; j++) zp[j] = fmul(zp[j - 1], z);
    { fe t = fmul(zp[n - 1], z); if (!(t.a == 1 && t.b == 0)) { fprintf(stderr, "order\n"); return 2; } }
    int pts[64];
    if (!strcmp(argv[5], "all")) {
        for (int i = 0; i < u; i++) pts[i] = i;
        for (;;) {
            seed(pts);
            int i = u - 1;
            while (i >= 0 && pts[i] == n - u + i) i--;
            if (i < 0) break;
            pts[i]++;
            for (int t = i + 1; t < u; t++) pts[t] = pts[t - 1] + 1;
        }
    } else if ((!strcmp(argv[5], "rand") || !strcmp(argv[5], "line")) && argc >= 8) {
        int line = !strcmp(argv[5], "line"), m = line ? u - 1 : u;
        if (m < 1) { fprintf(stderr, "seed size\n"); return 2; }
        u64 N = strtoull(argv[6], 0, 10), sd = strtoull(argv[7], 0, 10);
        for (int i = 0; i < 4; i++) { sd += 0x9e3779b97f4a7c15ULL; u64 x = sd; x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL; x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL; rs[i] = x ^ (x >> 31); }
        int pool[64];
        for (u64 s = 0; s < N; s++) {
            for (int j = 0; j < n - 1; j++) pool[j] = j + 1;
            pts[0] = 0;
            for (int i = 0; i < m - 1; i++) {
                int r = i + (int)below((u64)(n - 1 - i));
                int t = pool[i]; pool[i] = pool[r]; pool[r] = t; pts[i + 1] = pool[i];
            }
            if (line) line_seed(pts); else seed(pts);
        }
    } else { fprintf(stderr, "mode\n"); return 2; }
    printf("summary n=%d k=%d l=%d b=%d u=%d seeds=%llu singular=%llu dfs_nodes=%llu unique_solutions=%llu candidates=%d\n",
           n, k, l, b, u, (unsigned long long)n_seeds, (unsigned long long)n_singular, (unsigned long long)n_nodes,
           (unsigned long long)n_unique, nfound);
    return 0;
}
